descripcion:
.posts{

display:grid;
grid-template-columns:repeat(auto-fill,minmax(200px,1fr));
gap:20px;
margin-top:20px;

}

.card{

background:#222;
border-radius:8px;
overflow:hidden;
border:1px solid #333;
transition:0.3s;

}

.card:hover{

transform:scale(1.05);

}

.card img{

width:100%;
height:150px;
object-fit:cover;

}

.card h3{

padding:10px;
margin:0;

}

.card p{

padding:0 10px 10px;
font-size:14px;
color:#aaa;

}

